/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X firmware for the M-VAVE FM-1: one compilation unit for the platform and the app
 * (Felucca's layout: the HAL is header-only, so everything that touches it is here).
 * The DSP (dsp/), the sequencer (seq/) and the audio engine (app/engine.c) are separate
 * units compiled at -O2 by tools/build.py; this one is -Os. Order matters. */
#include <stdint.h>
#include "fm1_time.h"
#include "fm1_sys.h"
#include "fm1_irq.h"
#include "fm1_guard.h"
#if BOARD_SMK37
#define SMK_BIG __attribute__((section(".pool")))   /* SMK buffers in the pool (zeroed at boot): .data+.bss is full */
#include "smk_input.h"               /* SMK-37 Pro: keybed, pads, buttons, encoders, faders, wheels (fm1_input.h API) */
#else
#include "fm1_input.h"
#endif
#include "fm1_timer.h"
#include "fm1_audio.h"
#if !BOARD_SMK37
#include "fm1_adc.h"                 /* (SMK: smk_input.h stands in for it) */
#endif
#include "fm1_lcd_hw.h"
#include "fm1_cpu1.h"
#include "fm1_flash.h"
/* Production admission wiring; standalone host modules default to no maintenance. */
#define ST_MAINTENANCE_ADMIT() fm1_capture_pre_admit()
#define OTA_MAINTENANCE_ADMIT() fm1_capture_pre_admit()
#define ED_MAINTENANCE_ADMIT() fm1_capture_pre_admit()
#define ED_MAINTENANCE_HELD() fm1_capture_maintenance_held()
#include "fm1_xip.h"
#include "fm1_perf.h"

#include "libc.c"
#include "lcd.c"
#include "gfx.c"

static volatile uint32_t fm1_ms;  /* milliseconds since boot (TIMER4-based, TIMER5 ISR) */
#define RING_PUBLISH() __asm__ volatile("" ::: "memory")
static inline int32_t clamp(int32_t v, int32_t lo, int32_t hi) { return v < lo ? lo : v > hi ? hi : v; }

#include "app/plat.h"

#define FELUCCA_OTA 1             /* M-UPGRADE update entry: keeps the web installer working */
#ifndef X0X_CDC
#define X0X_CDC 0                 /* USB serial console off: one plain MIDI interface */
#endif
#define FELUCCA_CDC X0X_CDC
#ifndef X0X_UAC
#define X0X_UAC 1                 /* USB audio input: the master output, recordable over the cable */
#endif
#define FELUCCA_UAC X0X_UAC
#ifndef FELUCCA_ID
#if BOARD_SMK37
#define FELUCCA_ID "SMK-37 Pro_900"   /* package identity (tools/build.py) */
#else
#define FELUCCA_ID "FM-1_900"     /* package identity (tools/build.py) */
#endif
#endif
#include "usb.c"
#ifndef X0X_TRS
#if BOARD_SMK37
#define X0X_TRS 0                 /* SMK-37 Pro: no MIDI IN (its jack is MIDI OUT, UART1 TX on PC7); PH8 is a
                                   * key-matrix row there and must never become UART RX */
#else
#define X0X_TRS 1                 /* MIDI IN on the TRS jack */
#endif
#endif
#if BOARD_SMK37 && X0X_TRS
#error "BOARD_SMK37: midi_uart.c is the FM-1 MIDI IN driver (RX on PH8, a key-matrix row on the SMK)"
#endif
#if X0X_TRS
#include "midi_uart.c"
#endif

static uint8_t flash_ok;          /* JEDEC id matched at boot */
static void audio_silence(void);
static int st_read(uint32_t off, void *dst, uint32_t n)   /* 256-byte IRQ-off windows: audio keeps up */
{
    uint8_t *d = dst;
    int rc = 0;
    (void)FL_PARK();                         /* a Bluetooth controller on core 1: in RAM meanwhile */
    while (n) {
        uint32_t k = n > 256u ? 256u : n, f = irq_save();
        rc = FL_FAR(fl_read_ram)(off, d, k);
        irq_restore(f);
        if (rc)
            break;
        off += k;
        d += k;
        n -= k;
    }
    FL_UNPARK();
    return rc;
}
static int st_erase(uint32_t off)
{
    uint32_t took;
    if (!FL_STORE_OK(off, 0x1000u))
        return -8;
    audio_silence();
    return fl_erase4k(off, &took);
}
static int st_prog(uint32_t off, const void *src, uint32_t n)
{
    if (!FL_STORE_OK(off, n))
        return -8;
    return fl_write(off, src, n);
}
#define ST_IDLE() fm1_wdt_feed()   /* (storage.c, SMK store owner check: between sector erases) */
#include "storage.c"

struct bootguard_s { uint32_t magic, failed, pending; };
extern struct bootguard_s bootguard;
/* One 4 KiB scratch for main-loop jobs that never use the same bytes at the same time:
 *   0x000-0xFFF  the LZ hash table of a project save (lz.c);
 *   0x000-0x7FF  the read buffers of an update session (ota.c);
 *   0x000-0xCEF  the PERF TEST patterns and sound (ui.c, PERF_SCRATCH);
 *   0xD00-0xF7F  the decoded host message of ota.c (OTA_FRAME_MAX), read only in the call that decoded it;
 *   0xD00-0xEFF  editor sample/project chunk staging (editor.c, ED_SMP_SCRATCH), 512 B — same
 *                ownership class as ota_dec: live only inside one ed_handle. ed_service runs
 *                before ota_service; an editor frame is consumed before ota_take can write
 *                ota_dec. SAVE/LOAD paths that call lz_compress do not use ed_smp_buf. An
 *                update session does not call ed_service (blocked in ota_session / ota_idle).
 *   0xF80-0xFEF  the update parameter block (ota.c, 112 B). It is filled only after ota_stage
 *                returns, and ota_commit resets before the main loop can save. A save's LZ table
 *                uses this tail at every other time. ota_dec stops at 0xF7F, so a frame cannot
 *                reach it. The audio interrupt does not use this scratch.
 * A save does not run while the PERF TEST plays its patterns (seq.playing blocks it), and the test
 * makes its patterns after the last possible save (ui.c perf_test_tick, phase 0). An update session
 * stops the sequencer first, and the test then stops and puts the project back. */
_Static_assert(0xD00 + 640 <= 4096, "scratch");
_Static_assert(512u <= 640u, "ed_smp_buf fits the ota_dec region");
static uint16_t x0x_main_scratch[2048] __attribute__((aligned(4)));
#define OTA_SCRATCH ((uint8_t *)x0x_main_scratch)
#define OTA_DEC_OFF 0xD00u
#define LZ_SCRATCH x0x_main_scratch
#define PERF_SCRATCH x0x_main_scratch
#define ED_SMP_SCRATCH (OTA_SCRATCH + OTA_DEC_OFF)   /* 512 B; call-scoped like ota_dec */
#define OTA_PARM_OFF 0xF80u
#define OTA_PARM_N 112u
_Static_assert(OTA_DEC_OFF + 640u <= OTA_PARM_OFF, "update parm overlaps the decoded frame");
_Static_assert(OTA_PARM_OFF + OTA_PARM_N <= sizeof x0x_main_scratch, "update parm fits the scratch");
#include "ota.c"
static uint32_t ota_now_ms(void) { return fm1_ms; }
static void ota_idle(void) { fm1_wdt_feed(); }
static int ota_in_area(uint32_t off, uint32_t n) { return FL_IN(off, n, OTA_AREA, OTA_AREA + OTA_AREA_LEN); }
static int ota_erase(uint32_t off)
{
    uint32_t took;
    if (!ota_in_area(off, 0x1000u) || (off & 0xFFFu))
        return -8;
    audio_silence();
    return fl_erase4k(off, &took);
}
static int ota_prog(uint32_t off, const void *p, uint32_t n)
{
    if (!ota_in_area(off, n))
        return -8;
    return fl_write(off, p, n);
}
static int ota_fread(uint32_t off, void *p, uint32_t n) { return st_read(off, p, n); }
static void ota_show(uint32_t step, int32_t code)
{
#if BOARD_SMK37   /* step 5 stays on screen while the loader writes the flash: say so */
    static const char *const STEP[] = {"", "PACKAGE", "CHECK HEAD", "LOADER", "CONFIRM", "UPDATING..."};
#else
    static const char *const STEP[] = {"", "PACKAGE", "CHECK HEAD", "LOADER", "CONFIRM", "RESTART"};
#endif
    lcd_fill(0, 0, 240, 240, C_BLACK);
    draw_text_box(0, 92, 240, &FONT_S, "UPDATE", C_WHITE, 1);
    if (step < 9u) {
        draw_text_box(0, 124, 240, &FONT_S, STEP[step < 6u ? step : 0], C_HI, 1);
        return;
    }
    draw_text_box(0, 124, 240, &FONT_S, code == 1 ? "DRY RUN OK" : "FAILED", C_HI, 1);
    fm1_delay_ms(1500);
}
static void ota_commit(const uint8_t *parm)
{
    bootguard.pending = 0;                              /* intentional reset */
    bootguard.failed = 0;                               /* a new install starts with a clean slate */
    usb_detach();
    fm1_delay_ms(30);
    fm1_enter_update(parm);
}

#ifndef X0X_BLE
#define X0X_BLE BOARD_SMK37          /* Bluetooth MIDI through a separate controller image (src/ble.c) */
#endif
#if X0X_BLE
#include "ble.c"
#endif

#include "app/slots.c"
#include "app/x0x.h"
#include "app/chicago_param_tables.c" /* one Chicago Arp/FX/aux pot table for engine + UI */
#include "app/smk_clip_arp_share.c"   /* one ck_arp_pick + CK_RATE_T for engine + clip MIDI */
#include "app/smc_fx_map_tables.c"    /* one SMC FX map table for engine + smc_mixer */
#include "app/factory_banks.c"       /* built-in Chicago/Miami factory banks + user import bank */
#include "app/panel.c"
#include "app/plat_fm1.c"
/* Project objects are built in the store buffer. st_save reads the old copy's
 * sequence without loading its payload, so those new bytes stay. A boot upload
 * holds the buffer; project_save returns before it writes. Panel save passes
 * its own struct and copies in. The audio interrupt does not use this buffer. */
#define PROJECT_IO_BUFFER st_buf
_Static_assert(sizeof st_buf >= PLAT_STORE_MAX, "project object fits the store buffer");
#include "app/project.c"
#include "app/ui.c"
#if BOARD_SMK37
#include "app/smc_mixer.c"
#endif
#include "app/editor.c"
#include "app/main_fm1.c"

/* SPDX-License-Identifier: GPL-3.0-only
 * SMK-37 Pro port: Copyright (C) 2026 M. Geisler (genkigenki/makkuro) */
/* SMK-37 Pro flash map (build with -DBOARD_SMK37=1):
 * every 4 KiB sector of the 1 MiB part through the app's allow-list (FL_RANGE_OK / FL_GUARD, fm1_flash.h),
 * the update loader's (loader.c) and ldr_core.c's record window: none of them may ever reach
 * the head 0x0-0x3FFF, BTIF / USRTRIM 0xC0000-0xC1FFF, USR 0xF4000-0xFDFFF or key_mac 0xFF000-;
 * X0X's store objects (storage.c), its user sample slots (app/slots.c), the store owner tag and the OTA
 * staging (ota.c) lie inside the allowed windows; the store and the slots do not overlap; the Bluetooth
 * block is one 64 KiB piece of the app area; ranges that wrap or straddle a boundary are refused. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "fm1_cc.h"
#if !BOARD_SMK37
#error "build with -DBOARD_SMK37=1"
#endif

#include "fm1_flash_map.h"

static int st_read(uint32_t off, void *dst, uint32_t n) { (void)off; (void)dst; (void)n; return -1; }
static int st_erase(uint32_t off) { (void)off; return -1; }
static int st_prog(uint32_t off, const void *src, uint32_t n) { (void)off; (void)src; (void)n; return -1; }
#include "../firmware/src/app/plat.h"         /* X0X: the object map */
#include "../firmware/src/storage.c"
#define SMP_USER_XIP(k) ((const uint8_t *)0)  /* (slots.c: only its map is used here) */
#include "../firmware/src/app/slots.c"
#include "../firmware/src/app/boot_screen.h"
#define LDR_RANGE_OK(off, n) FL_LDR_RANGE_OK(off, n)       /* what loader.c uses on the SMK */

static int bad;
static void check(const char *what, int ok) { printf("smk flash: %-78s %s\n", what, ok ? "ok" : "FAIL"); bad += !ok; }

static int protected_sector(uint32_t s)
{
    return s < 0x4000u || (s >= 0xC0000u && s < 0xC2000u) || (s >= 0xF4000u && s < 0xFE000u) || s >= 0xFF000u;
}

int main(void)
{
    uint32_t s, o, c, k, leak_app = 0, leak_ldr = 0, leak_guard = 0, allowed = 0, in_store = 1, slots_ok = 1;
    for (s = 0; s < 0x100000u; s += 0x1000u) {
        if (!protected_sector(s))
            continue;
        leak_app += FL_RANGE_OK(s, 0x1000u) || FL_STORE_OK(s, 0x1000u) || FL_RANGE_OK(s, 256u) || FL_RANGE_OK(s + 0xF00u, 256u);
        leak_ldr += LDR_RANGE_OK(s, 0x1000u) || LDR_RANGE_OK(s + 0xF00u, 256u);
        leak_guard += !FL_PROTECTED(s, 0x1000u) || !FL_PROTECTED(s + 0xF00u, 256u);
    }
    for (s = 0; s < 0x100000u; s += 0x1000u)
        allowed += FL_GUARD(s, 0x1000u);
    check("no protected sector passes the app's allow-list (erase, page)", leak_app == 0);
    check("no protected sector passes the loader's allow-list", leak_ldr == 0);
    check("the RAM driver's own net (FL_PROTECTED) covers every protected sector", leak_guard == 0);
    check("straddling ranges refused: 0xBF000+0x2000, 0xF3000+0x2000, 0x3000+0x2000",
          !FL_GUARD(0xBF000u, 0x2000u) && !FL_GUARD(0xF3000u, 0x2000u) && !LDR_RANGE_OK(0xBF000u, 0x2000u) &&
          !LDR_RANGE_OK(0x3000u, 0x2000u) && FL_PROTECTED(0xBF000u, 0x2000u) && FL_PROTECTED(0x3F00u, 0x200u));
    check("wrapping ranges refused (off + n past 4 GiB)",
          !FL_GUARD(0xBB000u, 0xFFFFF000u) && !LDR_RANGE_OK(0x9D000u, 0xFFFFFF00u) && FL_PROTECTED(0xBB000u, 0xFFFFF000u));
    check("app windows: FL_DATA 0x9D000-0xAFFFF, FL_SMPV 0xB0000-0xBAFFF, FL_OTA 0xBB000-0xBFFFF, FL_SMP 0xC2000-0xF3FFF",
          FL_GUARD(0x9D000u, 0x1000u) && FL_GUARD(0xAF000u, 0x1000u) && FL_GUARD(0xB0000u, 0x1000u) &&
          FL_GUARD(0xBA000u, 0x1000u) && FL_GUARD(0xBF000u, 0x1000u) && FL_GUARD(0xC2000u, 0x1000u) &&
          FL_GUARD(0xF3000u, 0x1000u) && !FL_GUARD(0xF4000u, 0x1000u) && !FL_GUARD(0x9C000u, 0x1000u) &&
          FL_DATA_HI == 0xB0000u && allowed == (0xC0000u - 0x9D000u + 0xF4000u - 0xC2000u) / 0x1000u);
    check("FL_DATA (the store) and FL_SMPV (VM spare) do not overlap: no store sector in 0xB0000-0xBAFFF",
          FL_IN(0xAF000u, 0x1000u, FL_DATA_LO, FL_DATA_HI) && !FL_IN(0xB0000u, 0x1000u, FL_DATA_LO, FL_DATA_HI) &&
          FL_IN(0xB0000u, 0xB000u, FL_SMPV_LO, FL_SMPV_HI));
    check("Bluetooth block 0x8B000-0x9AFFF: 64 KiB, one piece, sector aligned, in FL_APP below the app slot end",
          FL_BLE_LO == 0x8B000u && FL_BLE_HI == 0x9B000u && FL_BLE_HI - FL_BLE_LO == 0x10000u &&
          FL_LDR_RANGE_OK(FL_BLE_LO, FL_BLE_HI - FL_BLE_LO) && !FL_GUARD(FL_BLE_LO, 0x1000u) &&
          FL_BLE_HI <= 0x4120u + 0x97400u && FL_APP_CODE_MAX == 0x86EE0u);
    check("loader: app area 0x4000-0x9CFFF, records 0x9D000-0xBFFFF only",
          LDR_RANGE_OK(0x4000u, 0x1000u) && LDR_RANGE_OK(0x9C000u, 0x1000u) && LDR_RANGE_OK(0xBF000u, 0x1000u) &&
          !LDR_RANGE_OK(0xC0000u, 0x1000u) && FL_REC_HI == 0xC0000u);
    for (o = 0; o < OBJ_NOBJ; o++)
        for (c = 0; c < 2u; c++)
            in_store &= FL_STORE_OK(st_sector(o, c), 0x1000u) && st_sector(o, c) < ST_OWNER_SECTOR;
    {   /* every object's two copies distinct */
        uint32_t o2, c2, distinct = 1;
        for (o = 0; o < OBJ_NOBJ; o++)
            for (c = 0; c < 2u; c++)
                for (o2 = 0; o2 < OBJ_NOBJ; o2++)
                    for (c2 = 0; c2 < 2u; c2++)
                        if ((o != o2 || c != c2) && st_sector(o, c) == st_sector(o2, c2))
                            distinct = 0;
        check("storage.c: every object (A/B) in FL_DATA below the owner tag, no two share a sector", in_store && distinct);
    }
    check("storage.c: settings 0x9D000/0x9E000, motion up to 0xAAFFF",
          st_sector(OBJ_SET, 0) == 0x9D000u && st_sector(OBJ_SET, 1) == 0x9E000u &&
          st_sector(OBJ_MOTION, 1) == 0xAA000u);
    check("boot screen A/B follows the objects, inside the store, short of the owner tag",
          BOOT_SEC0 == 0xAB000u && BOOT_SEC1 == 0xAC000u && st_sector(OBJ_MOTION, 1) + 0x1000u == BOOT_SEC0 &&
          FL_GUARD(BOOT_SEC0, 0x1000u) && FL_GUARD(BOOT_SEC1, 0x1000u) && BOOT_SEC1 + 0x1000u < ST_OWNER_SECTOR &&
          !FL_GUARD(0xFF000u, 0x1000u));
    check("store owner tag 0xAF000: in FL_DATA, the convention of every SMK port",
          ST_OWNER_SECTOR == 0xAF000u && FL_GUARD(ST_OWNER_SECTOR, 0x1000u));
    for (k = 0; k < SMP_USER_SLOTS; k++) {
        uint32_t k2;
        slots_ok &= FL_GUARD(SMP_USER_OFF(k), SMP_USER_SIZE(k)) && SMP_USER_OFF(k) % 0x1000u == 0u &&
                    SMP_USER_SIZE(k) % 0x1000u == 0u && SMP_USER_SIZE(k) <= SMP_USER_MAX &&
                    !FL_IN(SMP_USER_OFF(k), 0x1000u, FL_DATA_LO, FL_DATA_HI) &&
                    (SMP_USER_OFF(k) >= ST_OWNER_SECTOR + 0x1000u || SMP_USER_OFF(k) + SMP_USER_SIZE(k) <= ST_SMK_BASE);
        for (k2 = 0; k2 < SMP_USER_SLOTS; k2++)
            slots_ok &= k == k2 || SMP_USER_OFF(k) + SMP_USER_SIZE(k) <= SMP_USER_OFF(k2) ||
                        SMP_USER_OFF(k2) + SMP_USER_SIZE(k2) <= SMP_USER_OFF(k);
    }
    check("slots.c: 2 slots, 0xC2000 80 KiB, 0xD6000 120 KiB: allowed, apart, outside the store",
          SMP_USER_SLOTS == 2 && SMP_USER_OFF(0u) == 0xC2000u && SMP_USER_SIZE(0u) == 0x14000u &&
          SMP_USER_OFF(1u) == 0xD6000u && SMP_USER_SIZE(1u) == 0x1E000u && slots_ok);
    check("slots 1 and 2 keep the offsets of the 2 x 80 KiB layout (their data stays valid)",
          SMP_USER_OFF(0u) == 0xC2000u && SMP_USER_OFF(1u) == 0xC2000u + 0x14000u);
    check("no slot in the install range [0x4000, 0x9D000) or in the VM spare 0xB0000-0xBAFFF",
          SMP_USER_OFF(0u) >= 0x9D000u && SMP_USER_OFF(0u) >= 0xBB000u && SMP_USER_OFF(1u) >= 0xBB000u);
    check("FL_PLAIN_LO = the VM start 0x9D000", FL_PLAIN_LO == 0x9D000u);
    check("FL_JEDEC_OK: the SMK part 0xEB6014 and 0x856014 only", FL_JEDEC_OK(0xEB6014u) && FL_JEDEC_OK(0x856014u) &&
          !FL_JEDEC_OK(0u) && !FL_JEDEC_OK(0xFFFFFFu) && !FL_JEDEC_OK(0xEB6015u));
    printf("%s\n", bad ? "SMK FLASH TEST FAILED" : "smk flash test passed");
    return bad != 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Real SMC MIDI queue/dispatch + UI/engine: SELECT belongs to its press mode. */
#include <stdint.h>
#define SMC_UI_SEND_IMPLEMENTED 1
static uint8_t select_led_velocity[8];
int plat_ble_smc_send(const uint8_t *m, uint8_t n)
{
    if (n == 3 && m[0] == 0x90 && m[1] >= 24 && m[1] < 32)
        select_led_velocity[m[1] - 24] = m[2];
    return 1;
}
#define SMC_UI_MAIN smc_ui_existing_main
#include "smc_ui_test.c"
#undef SMC_UI_MAIN

static void check_select_led(int strip, int on)
{
    smc_frame();
    CHECK(smc_led(24 + strip) == !!on);
    CHECK(select_led_velocity[strip] == (on ? 127 : 0));
}
static void check_main_navigation_leds(void)
{
    check_select_led(5, ui.view == V_FX && cur_page() == 0);
    check_select_led(6, ui.view == V_FX && cur_page() == 1);
    check_select_led(7, ui.view == V_MIX && cur_page() == 3);
}
static void check_plain_leds(void)
{
    const int views[] = {V_HOME, V_PART, V_SEQ, V_GEN, V_MIX, V_GLO, V_SONG};
    for (unsigned v = 0; v < sizeof views / sizeof *views; v++) for (int part = 0; part < NPARTS; part++) {
        if (views[v] == V_GEN && part != PART_303A && part != PART_303B) continue;
        setup(views[v], part);
        if (views[v] == V_SEQ && part < NKIT) {
            /* Drum SEQ retains sound-bank selection, including the final partial bank. */
            for (int track = 0; track < NDRUM; track++) {
                ui.sel[part] = (uint8_t)track; build_pages();
                for (int strip = 0; strip < 8; strip++) check_select_led(strip, strip == track % 8);
            }
        } else {
            for (int strip = 0; strip < NPARTS; strip++) check_select_led(strip, strip == (part==2?4:part==4?2:part));
        }
    }
}
static void check_plain_select(void)
{
    const int views[] = {V_HOME, V_PART, V_SEQ, V_GEN, V_MIX, V_GLO, V_SONG};
    for (unsigned v = 0; v < sizeof views / sizeof *views; v++) for (int strip = 0; strip < 8; strip++) {
        setup(views[v], strip == PART_BRK ? PART_303A : PART_BRK);
        if (views[v] == V_GEN) { ui.part = PART_303A; build_pages(); }
        int rec = ui.rec;
        message(0x90, 24 + strip, 127);
        CHECK(!smc.fx_down && !smc.fx_main_wait);
        if (strip < NPARTS) { CHECK(ui.part == (strip==2?4:strip==4?2:strip)); CHECK(ui.view == V_PART); check_select_led(strip, 1); }
        else { CHECK(ui.view == (strip == 7 ? V_MIX : V_FX)); CHECK(cur_page() == (strip == 5 ? 0 : strip == 6 ? 1 : 3)); }
        int view = ui.view, page = cur_page(), part = ui.part;
        message(0x90, 24 + strip, 127); /* repeat cannot acquire FX after navigation */
        now_ms += 200; smc_poll();
        CHECK(!smc.fx_down && !smc.fx_main_wait);
        message(0x80, 24 + strip, 0);
        CHECK(ui.view == view && cur_page() == page && ui.part == part);
        if (strip < NPARTS) check_select_led(strip, 1);
        else check_main_navigation_leds();
        CHECK(ui.rec == rec && !seq.req_start && !seq.req_stop);
    }
}
static void check_fx_and_release(void)
{
    for (int strip = 0; strip < 8; strip++) {
        setup(V_FX, PART_303A);
        int part = ui.part;
        message(0x90, 24 + strip, 127);
        if (strip < 5) { CHECK(smc.fx_down == (1u << (strip==2?4:strip==4?2:strip)));
            for (int lane = 0; lane < NPARTS; lane++) check_select_led(lane, lane == strip);
        }
        else { CHECK(!smc.fx_down); CHECK(smc.fx_main_wait == (1u << (strip - 5)));
            check_main_navigation_leds(); /* pending hold retains its navigation indication */
        }
        now_ms += 200; smc_poll(); CHECK(smc.fx_down == (1u << (strip==2?4:strip==4?2:strip)));
        if (strip < NPARTS) check_select_led(strip, 1);
        else check_main_navigation_leds();
        CHECK(ui.view == V_FX && ui.part == part);
        message(0x90, 24 + strip, 0); /* captured preset sends NoteOn zero */
        CHECK(!smc.fx_down && !smc.fx_main_wait);
        CHECK(ui.view == V_FX && ui.part == part);
        if (strip < NPARTS) check_select_led(strip, 0);
        else check_main_navigation_leds();
    }
    setup(V_FX, PART_303A);
    message(0x90, 27, 127);
    CHECK(smc.fx_effect[SMCFX_303B] == SMCFX_LP); /* ROOM defaults: 303B SELECT is low-pass */
}
static void check_main_taps(void)
{
    for (int strip = 5; strip < 8; strip++) {
        setup(V_FX, PART_303A);
        message(0x90, 24 + strip, 127);
        message(0x80, 24 + strip, 0);
        CHECK(ui.view == (strip == 7 ? V_MIX : V_FX));
        CHECK(cur_page() == (strip == 5 ? 0 : strip == 6 ? 1 : 3));
        CHECK(!smc.fx_down && !smc.fx_main_wait);
        check_select_led(5, strip == 5); check_select_led(6, strip == 6); check_select_led(7, strip == 7);
    }
    setup(V_FX, PART_303A);
    message(0x90, 27, 127); CHECK(smc.fx_down);
    message(0x90, 31, 127); message(0x80, 31, 0);
    CHECK(ui.view == V_MIX && !smc.fx_down && !smc.fx_main_wait);
    message(0x80, 27, 0); CHECK(ui.view == V_MIX && !smc.fx_down);
}
static void check_mode_changes(void)
{
    const int views[] = {V_HOME, V_PART, V_SEQ, V_GEN, V_MIX, V_GLO, V_SONG};
    for (unsigned v = 0; v < sizeof views / sizeof *views; v++) for (int strip = 0; strip < 8; strip++) for (int hold = 0; hold < 2; hold++) {
        setup(V_FX, PART_303A);
        message(0x90, 24 + strip, 127);
        if (hold) { now_ms += 200; smc_poll(); }
        ui.part = views[v] == V_SEQ || views[v] == V_MIX ? PART_909 : PART_303A;
        set_view(views[v]); build_pages();
        int part = ui.part, page = cur_page();
        smc_poll(); CHECK(!smc.fx_down && !smc.fx_main_wait);
        check_main_navigation_leds();
        if (views[v] != V_SEQ && views[v] != V_MIX)
            for (int lane = 0; lane < NPARTS; lane++) check_select_led(lane, lane == (part==2?4:part==4?2:part));
        message(0x80, 24 + strip, 0);
        CHECK(!smc.fx_down && !smc.fx_main_wait);
        CHECK(ui.view == views[v] && ui.part == part && cur_page() == page);
        /* A late release after returning to FX must not navigate a main strip. */
        set_view(V_FX); *page_of(V_FX) = strip == 6 ? 0 : 1; build_pages();
        int fx_page = cur_page();
        message(0x80, 24 + strip, 0);
        CHECK(ui.view == V_FX && cur_page() == fx_page && !smc.fx_down);
        for (int lane = 0; lane < NPARTS; lane++) check_select_led(lane, 0);
        check_main_navigation_leds();
    }
    /* Release clears its original FX before a poll can reconcile a new drum bank. */
    setup(V_FX, PART_303A); message(0x90, 27, 127); CHECK(smc.fx_down);
    ui.part = PART_909; set_view(V_SEQ); build_pages(); smc_release(27);
    CHECK(!smc.fx_down && !smc.fx_main_wait);
}
int main(void)
{
    check_plain_leds(); check_plain_select(); check_fx_and_release(); check_main_taps(); check_mode_changes();
    printf("PASS SMC SELECT mode ownership: %u production-input checks\n", checks);
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* The 909 cymbals as IMA ADPCM (drum909.c, ima_adpcm.h, tools/gen_drum_samples.py):
 *   1. the firmware decoder gives the reference samples (tests/host/cymbal_ref.py: the approved
 *      A/B study's decode when it is there) within 1 LSB, and the SNR against the original PCM;
 *   2. d9_render_smp's forward streaming decode gives bit-identical output to the old read loop
 *      on a fully decoded int16 buffer, at pitch 0.25 ... 4 (inc up to 4: up to 4 decodes a sample),
 *      and again after a retrigger part way through;
 *   3. the cost: decodes per output sample at each pitch, and the time per decode on the host.
 *   drum909_adpcm_test REFDIR */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "../../firmware/src/dsp/x0x_param.c"
#include "../../firmware/src/dsp/drum909.c"

static int16_t *load(const char *dir, const char *name, const char *ext, uint32_t n)
{
    char p[512];
    snprintf(p, sizeof p, "%s/%s.%s", dir, name, ext);
    FILE *f = fopen(p, "rb");
    if (!f) { printf("FAIL cannot open %s\n", p); exit(1); }
    int16_t *b = malloc(n * 2);
    if (fread(b, 2, n, f) != n) { printf("FAIL short %s\n", p); exit(1); }
    fclose(f);
    return b;
}

/* the read loop before this change (int16 buffer), mute and envelope as 1 */
static uint32_t play_pcm(const int16_t *buf, uint32_t len, float pitch, float *out, uint32_t max)
{
    d9_smp_t s;
    memset(&s, 0, sizeof s);
    s.pitch = pitch;
    d9_smp_rate(&s);
    uint32_t k = 0;
    while (s.pos < len && k < max) {
        const float a = (float)buf[s.pos] * (1.0f / 32768.0f);
        const float b = s.pos + 1 < len ? (float)buf[s.pos + 1] * (1.0f / 32768.0f) : 0.0f;
        const float fr = (float)s.frac * (1.0f / 4294967296.0f);
        out[k++] = a + (b - a) * fr;
        const uint32_t f2 = s.frac + s.incf;
        s.pos += s.inc + (f2 < s.frac);
        s.frac = f2;
    }
    return k;
}

static void trig(d9_smp_t *s)
{
    s->pos = s->frac = 0;
    s->dk = 0;
    s->pred = s->idx = 0;
    s->h0 = s->h1 = 0;
    s->playing = 1;
    s->mute = 0x7FFFFFFF;
    d9_env_set(&s->out, 1.0f);
}

/* the firmware render (streaming ADPCM), in blocks of 32; returns samples until pos >= len */
static uint32_t play_adpcm(d9_smp_t *s, float *out, uint32_t max, uint32_t *decodes)
{
    static float dry[32];
    d9_bus_t bus;
    memset(&bus, 0, sizeof bus);
    bus.dry = dry;
    uint32_t k = 0;
    while (s->pos < s->len && k < max) {
        memset(dry, 0, sizeof dry);
        d9_render_smp(s, &bus, 32);
        for (int i = 0; i < 32 && k < max; i++)
            out[k++] = dry[i];
    }
    if (decodes) *decodes = s->dk;
    return k;
}

int main(int argc, char **argv)
{
    if (argc < 2) { fprintf(stderr, "usage: %s REFDIR\n", argv[0]); return 2; }
    struct { const char *name; const uint8_t *adpcm; uint32_t len, bytes; } C[3] = {
        {"hh", x0x_smp_hh, X0X_SMP_HH_LEN, sizeof x0x_smp_hh},
        {"ride", x0x_smp_ride, X0X_SMP_RIDE_LEN, sizeof x0x_smp_ride},
        {"crash", x0x_smp_crash, X0X_SMP_CRASH_LEN, sizeof x0x_smp_crash}};
    static const float PITCH[] = {0.25f, 0.5f, 0.7937005f, 1.0f, 1.3348398f, 2.0f, 3.1748021f, 4.0f};
    int bad = 0;
    uint32_t flash = 0, pcm_bytes = 0;
    for (int c = 0; c < 3; c++) {
        const uint32_t n = C[c].len;
        int16_t *ref = load(argv[1], C[c].name, "ref", n), *pcm = load(argv[1], C[c].name, "pcm", n);
        int16_t *dec = malloc(n * 2);
        int32_t pred = 0, idx = 0, maxd = 0;
        double es = 0, ps = 0;
        for (uint32_t i = 0; i < n; i++) {
            dec[i] = (int16_t)ima_decode(C[c].adpcm, i, &pred, &idx);
            int32_t d = abs(dec[i] - ref[i]);
            if (d > maxd) maxd = d;
            es += (double)(dec[i] - pcm[i]) * (dec[i] - pcm[i]);
            ps += (double)pcm[i] * pcm[i];
        }
        flash += C[c].bytes;
        pcm_bytes += n * 2;
        const double snr = 10.0 * log10(ps / es);
        const int ok = maxd <= 1 && C[c].bytes == (n + 1) / 2 && snr > 15.0;
        printf("  %s %-5s %6u samples, %5u B ADPCM (int16 %6u B), max |decode - ref| %d LSB, SNR %.1f dB\n",
               ok ? "ok  " : "FAIL", C[c].name, n, C[c].bytes, n * 2, maxd, snr);
        bad += !ok;

        /* streaming against the full decode, every pitch */
        float *a = malloc(sizeof(float) * (4 * n + 64)), *b = malloc(sizeof(float) * (4 * n + 64));
        for (unsigned p = 0; p < sizeof PITCH / sizeof PITCH[0]; p++) {
            d9_smp_t s;
            memset(&s, 0, sizeof s);
            s.adpcm = C[c].adpcm;
            s.len = n;
            s.pitch = PITCH[p];
            d9_smp_rate(&s);
            trig(&s);
            uint32_t dk = 0;
            const uint32_t na = play_pcm(dec, n, PITCH[p], a, 4 * n + 64);
            const uint32_t nb = play_adpcm(&s, b, 4 * n + 64, &dk);
            uint32_t diff = 0;
            for (uint32_t i = 0; i < na && i < nb; i++)
                diff += memcmp(&a[i], &b[i], sizeof(float)) != 0;
            /* nb is rounded up to the block: the samples after the end are 0 */
            for (uint32_t i = na; i < nb; i++)
                diff += b[i] != 0.0f;
            const int pk = na <= nb && diff == 0 && dk <= n && dk + 4 >= n;   /* the last few are skipped at high pitch */
            if (!pk || p == 0 || PITCH[p] == 4.0f)
                printf("  %s %-5s pitch %.3f: %u samples, %u differ, %u decodes (%.2f per output sample)\n",
                       pk ? "ok  " : "FAIL", C[c].name, (double)PITCH[p], na, diff, dk, (double)dk / na);
            bad += !pk;
        }
        /* a retrigger part way through: decoding starts again from the first nibble */
        {
            d9_smp_t s;
            memset(&s, 0, sizeof s);
            s.adpcm = C[c].adpcm;
            s.len = n;
            s.pitch = 1.3348398f;
            d9_smp_rate(&s);
            trig(&s);
            static float dry[32];
            d9_bus_t bus;
            memset(&bus, 0, sizeof bus);
            bus.dry = dry;
            for (int k = 0; k < 40; k++)
                d9_render_smp(&s, &bus, 32);
            trig(&s);
            const uint32_t na = play_pcm(dec, n, s.pitch, a, 4 * n + 64);
            const uint32_t nb = play_adpcm(&s, b, 4 * n + 64, NULL);
            uint32_t diff = 0;
            for (uint32_t i = 0; i < na && i < nb; i++)
                diff += memcmp(&a[i], &b[i], sizeof(float)) != 0;
            printf("  %s %-5s retrigger at 1280 samples: %u differ\n", diff ? "FAIL" : "ok  ", C[c].name, diff);
            bad += diff != 0;
        }
        free(a); free(b); free(dec); free(ref); free(pcm);
    }
    printf("  cymbals: %u B of ADPCM in flash, %u B as int16, %u B saved\n", flash, pcm_bytes, pcm_bytes - flash);

    /* host time per decode (a rough guide only; the device estimate is in BEHAVIOR.md DRM-12) */
    {
        volatile int32_t sink = 0;
        int32_t pred = 0, idx = 0;
        const clock_t t0 = clock();
        const int R = 200;
        for (int r = 0; r < R; r++) {
            pred = idx = 0;
            for (uint32_t i = 0; i < X0X_SMP_RIDE_LEN; i++)
                sink += ima_decode(x0x_smp_ride, i, &pred, &idx);
        }
        const double ns = (double)(clock() - t0) / CLOCKS_PER_SEC * 1e9 / ((double)R * X0X_SMP_RIDE_LEN);
        printf("  host: %.2f ns per decode (%d)\n", ns, (int)(sink & 1));
    }
    puts(bad ? "DRUM909 ADPCM FAILED" : "drum909 adpcm: decode and streaming ok");
    return bad ? 1 : 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* The BREAK part's default built-in loops, played by this firmware's own 909
 * (dsp/drum909.c) on the host at build time: two bars each at 96 BPM, a groove and a busier
 * fill. No recording ships: the loops are this code's output. Written as the break bank
 * header (the same format tools/gen_break_bank.py writes for an opt-in bank of WAVs):
 * IMA ADPCM, mono, 44100 Hz (no downsampling, no length cut), the format of the user sample slots.
 *   gen_builtin_break OUT.h [EXPORT_DIR]
 * EXPORT_DIR receives the same loops as WAV and ADPCM, so they can be installed
 * without living in the firmware image. The ADPCM is the header's bytes, uncut. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "dsp/drum909.h"

#define BPM 96.0
#define RATE 44100
#define BARS 2
#define STEPS (16 * BARS)

/* step strings: x = hit, X = accented hit, g = ghost (soft), . = rest */
typedef struct { int voice; const char *s; } lane_t;
static const lane_t GROOVE[] = {
    {DR_BD, "X.....x...x.....X.....x..x......"},
    {DR_SD, "....X..g.g..X..g....X..g.g..X.g."},
    {DR_CH, "x.x.x.x.x.x.x.x.x.x.x.x.x.x.x.x."},
    {DR_OH, "...............x...............x"},
    {DR_RD, "................................"},
};
static const lane_t FILL[] = {
    {DR_BD, "X.....x...x.x...X..x..x...x.x..."},
    {DR_SD, "....X..g.g.gX.gg....X.gX.gX.XgXX"},
    {DR_CH, "x.x.x.xxx.x.x.x.x.xxx.x.x.x....."},
    {DR_OH, ".......x.......x.......x........"},
    {DR_LT, "............................x..."},
    {DR_MT, "..........................x....."},
    {DR_HT, "........................x......."},
    {DR_CR, "................................"},
};

static int16_t *render(const lane_t *L, int nl, uint32_t *frames)
{
    static drum909_t d;
    float dry[256], rev[256], dly[256];
    double spb = RATE * 60.0 / BPM / 4.0;            /* samples per 16th */
    uint32_t total = (uint32_t)(spb * STEPS + 0.5), pos = 0, i;
    int16_t *out = malloc(sizeof(int16_t) * total);
    int step = 0;
    drum909_init(&d);
    while (pos < total) {
        uint32_t next = step < STEPS ? (uint32_t)(spb * step + 0.5) : total, n;
        if (pos >= next && step < STEPS) {
            int l;
            for (l = 0; l < nl; l++) {
                char c = L[l].s[step];
                if (c == 'x' || c == 'X' || c == 'g')
                    drum909_trigger(&d, L[l].voice, c == 'X' ? 1.0f : c == 'g' ? 0.35f : 0.75f);
            }
            step++;
            continue;
        }
        n = next - pos;
        if (n > 256)
            n = 256;
        memset(dry, 0, sizeof dry);
        memset(rev, 0, sizeof rev);
        memset(dly, 0, sizeof dly);
        drum909_render(&d, dry, rev, dly, (int)n);
        for (i = 0; i < n; i++) {
            float v = dry[i] * 1.6f;                   /* a loop is normalised, like a sampled break */
            v = v > 1.0f ? 1.0f : v < -1.0f ? -1.0f : v;
            out[pos + i] = (int16_t)(v * 32767.0f);
        }
        pos += n;
    }
    *frames = total;
    return out;
}

static const int16_t STEP_T[89] = {
    7, 8, 9, 10, 11, 12, 13, 14, 16, 17, 19, 21, 23, 25, 28, 31, 34, 37, 41, 45, 50, 55, 60, 66, 73, 80, 88, 97,
    107, 118, 130, 143, 157, 173, 190, 209, 230, 253, 279, 307, 337, 371, 408, 449, 494, 544, 598, 658, 724, 796,
    876, 963, 1060, 1166, 1282, 1411, 1552, 1707, 1878, 2066, 2272, 2499, 2749, 3024, 3327, 3660, 4026, 4428,
    4871, 5358, 5894, 6484, 7132, 7845, 8630, 9493, 10442, 11487, 12635, 13899, 15289, 16818, 18500, 20350,
    22385, 24623, 27086, 29794, 32767};
static const int8_t IDX_T[8] = {-1, -1, -1, -1, 2, 4, 6, 8};

/* IMA ADPCM at the render rate (44.1 kHz) from predictor 0 / index 0 (tools/sampleio.py's encoder) */
static uint8_t *adpcm(const int16_t *x, uint32_t n, uint32_t *ns)
{
    uint32_t m = n, i;
    uint8_t *o = calloc(1, m / 2 + 1);
    int pred = 0, idx = 0;
    for (i = 0; i < m; i++) {
        int s = x[i], step = STEP_T[idx], diff = s - pred, code = 0, vd = step >> 3;
        if (diff < 0) {
            code = 8;
            diff = -diff;
        }
        if (diff >= step) { code |= 4; diff -= step; vd += step; }
        if (diff >= step >> 1) { code |= 2; diff -= step >> 1; vd += step >> 1; }
        if (diff >= step >> 2) { code |= 1; vd += step >> 2; }
        pred = code & 8 ? pred - vd : pred + vd;
        pred = pred > 32767 ? 32767 : pred < -32768 ? -32768 : pred;
        idx += IDX_T[code & 7];
        idx = idx < 0 ? 0 : idx > 88 ? 88 : idx;
        if (i & 1)
            o[i >> 1] |= (uint8_t)(code << 4);
        else
            o[i >> 1] = (uint8_t)code;
    }
    *ns = m;
    return o;
}

/* A buffered output error may first appear when fclose flushes it. Close even
 * after an earlier write error, and never report a partial output as success. */
static int finish_output(FILE *f, const char *path)
{
    int failed = ferror(f);
    if (fclose(f) != 0)
        failed = 1;
    if (failed)
        fprintf(stderr, "builtin break: output failed: %s\n", path);
    return failed ? -1 : 0;
}

static int write_raw(const char *path, const uint8_t *d, uint32_t n)
{
    FILE *f = fopen(path, "wb");
    if (!f) {
        perror(path);
        return -1;
    }
    fwrite(d, 1, n, f);
    return finish_output(f, path);
}

static int write_wav(const char *path, const int16_t *x, uint32_t n)
{
    FILE *f = fopen(path, "wb");
    uint32_t data = n * 2u, riff = 36u + data, sixteen = 16u, rate = RATE, bps = RATE * 2u;
    uint16_t pcm = 1, ch = 1, bits = 16, block = 2;
    if (!f) {
        perror(path);
        return -1;
    }
    fwrite("RIFF", 1, 4, f);
    fwrite(&riff, 4, 1, f);
    fwrite("WAVEfmt ", 1, 8, f);
    fwrite(&sixteen, 4, 1, f);
    fwrite(&pcm, 2, 1, f);
    fwrite(&ch, 2, 1, f);
    fwrite(&rate, 4, 1, f);
    fwrite(&bps, 4, 1, f);
    fwrite(&block, 2, 1, f);
    fwrite(&bits, 2, 1, f);
    fwrite("data", 1, 4, f);
    fwrite(&data, 4, 1, f);
    fwrite(x, 2, n, f);
    return finish_output(f, path);
}

static void emit(FILE *f, const char *name, const uint8_t *d, uint32_t ns)
{
    uint32_t i, nb = (ns + 1) / 2;
    fprintf(f, "#define %s_N %uu\nstatic const uint8_t %s[%u] = {", name, ns, name, nb);
    for (i = 0; i < nb; i++)
        fprintf(f, "%s%u,", i % 24 ? "" : "\n    ", d[i]);
    fprintf(f, "\n};\n");
}

int main(int argc, char **argv)
{
    uint32_t fa, fb, na, nb;
    int result = 1;
    const char *header = argc > 1 ? argv[1] : "x0x_builtin_break.h";
    int16_t *a = render(GROOVE, (int)(sizeof GROOVE / sizeof GROOVE[0]), &fa);
    int16_t *b = render(FILL, (int)(sizeof FILL / sizeof FILL[0]), &fb);
    uint8_t *ea = adpcm(a, fa, &na), *eb = adpcm(b, fb, &nb);
    FILE *f = fopen(header, "w");
    if (!f) {
        perror(header);
        goto done;
    }
    fprintf(f, "/* Generated by tools/gen_builtin_break.c -- do not edit. The BREAK part's default\n"
               " * built-in loops: two bars at %g BPM played by this firmware's 909 port; IMA ADPCM,\n"
               " * mono, 44100 Hz. */\n#pragma once\n#include <stdint.h>\n"
               "#define X0X_NBREAKS 2\n#define X0X_BREAK_RATE 44100u\n", BPM);
    emit(f, "X0X_BREAK_0", ea, na);
    emit(f, "X0X_BREAK_1", eb, nb);
    fprintf(f, "typedef struct { const char *name; const uint8_t *adpcm; uint32_t n; uint8_t bars; } x0x_break_t;\n"
               "static const x0x_break_t X0X_BREAKS[X0X_NBREAKS] = {\n"
               "    {\"909 GR\", X0X_BREAK_0, X0X_BREAK_0_N, %d},\n    {\"909 FL\", X0X_BREAK_1, X0X_BREAK_1_N, %d},\n};\n",
            BARS, BARS);
    if (finish_output(f, header) != 0)
        goto done;
    if (argc > 2) {
        char path[512];
        FILE *m;
        if (snprintf(path, sizeof path, "%s/909GR.wav", argv[2]) >= (int)sizeof path)
            goto done;
        if (write_wav(path, a, na) != 0)
            goto done;
        if (snprintf(path, sizeof path, "%s/909FL.wav", argv[2]) >= (int)sizeof path)
            goto done;
        if (write_wav(path, b, nb) != 0)
            goto done;
        if (snprintf(path, sizeof path, "%s/909GR.adpcm", argv[2]) >= (int)sizeof path)
            goto done;
        if (write_raw(path, ea, (na + 1) / 2) != 0)
            goto done;
        if (snprintf(path, sizeof path, "%s/909FL.adpcm", argv[2]) >= (int)sizeof path)
            goto done;
        if (write_raw(path, eb, (nb + 1) / 2) != 0)
            goto done;
        if (snprintf(path, sizeof path, "%s/pack.txt", argv[2]) >= (int)sizeof path)
            goto done;
        m = fopen(path, "w");
        if (!m) {
            perror(path);
            goto done;
        }
        fprintf(m, "# file samples bars name — full loops, not a shared prefix\n");
        fprintf(m, "909GR.adpcm %u %d 909 GR\n", na, BARS);
        fprintf(m, "909FL.adpcm %u %d 909 FL\n", nb, BARS);
        if (finish_output(m, path) != 0)
            goto done;
    }
    printf("builtin break: A %u + B %u samples, %u bytes of flash\n", na, nb, (na + 1) / 2 + (nb + 1) / 2);
    result = 0;
done:
    free(a);
    free(b);
    free(ea);
    free(eb);
    return result;
}

