#!/usr/bin/env python3
"""Exercise production SMC link publication across a TIMER5 interruption.

The real edge notifier, link producer, queue producer, project reset and poller
are compiled together. UI/platform calls schedule an interrupt after the poller
has sampled the link. MIDI actions are recorded at the dispatch boundary.
SMC_SOURCE selects the unchanged source for the negative control.
"""
import os
from pathlib import Path
import re
import shlex
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
SOURCE = Path(os.environ.get("SMC_SOURCE", ROOT / "firmware/src/app/smc_mixer.c"))
source = SOURCE.read_text()
transport = (ROOT / "firmware/src/ble.c").read_text()


def function(text, name):
    match = re.search(r"^[^\n]*\b" + name + r"\([^\n]*\)\s*\{", text, re.M)
    if not match:
        raise RuntimeError(f"Production function not found: {name}")
    depth = 1
    end = match.end()
    while depth:
        if end == len(text):
            raise RuntimeError(f"Unterminated production function: {name}")
        depth += (text[end] == "{") - (text[end] == "}")
        end += 1
    return text[match.start():end]


prefix = source[source.index("#define SMC_Q"):source.index("int smc_project_active")]
has_generation = "smc_link_published" in prefix
harness = r'''
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "app/smc_protocol.h"
#include "smc_fx_harness_stubs.h"
#define X0X_COLD
#define PROJ_BT_SMC_CENTRAL 16u
#define PROJ_BT_SMC_USER 32u
typedef struct { uint8_t kind, a, b, c; } pref_t;
enum { O_NONE, O_ASK, NKIT = 2 };
static struct { struct { uint8_t bt; } set; } proj;
static struct { uint8_t overlay, help; } ui;
static int locked, interrupt_at, interrupt_up;
static unsigned dispatched, notices, solo;
static uint8_t observed[3][3];
static int perf_testing(void);
static int ui_project_busy(void);
static void engine_smc_solo(int n) { solo = (unsigned)n; }
static void ui_say(const char *a, const char *b) { (void)a; (void)b; notices++; }
#define smc_ui_cancel() ((void)0) /* Presentation is exercised by smc_ui_test.c. */
''' + prefix + "\n" + "\n".join(function(source, name) for name in
    ("smc_project_active", "smc_solo_clear") if "smc_solo_clear" in source) + "\n" + "\n".join(function(source, name) for name in (
    "smc_project_drop", "smc_project_reset", "smc_ble_midi", "smc_ble_link")) + r'''
static uint8_t ble_central_link_seen;
''' + function(transport, "ble_central_link_notify") + r'''

static void interrupt(int site)
{
    if (interrupt_at != site) return;
    interrupt_at = 0;
    ble_central_link_notify(interrupt_up);
}
static int perf_testing(void) { interrupt(1); return 0; }
static int ui_project_busy(void) { interrupt(2); return locked; }
static uint8_t smc_message(const uint8_t *m, uint8_t n, int allow)
{
    if (!allow || n != 3 || dispatched >= 3) abort();
    memcpy(observed[dispatched++], m, 3);
    return 0;
}
static void smc_guarded_button(uint8_t n, int mmc, int allow)
{ (void)n; (void)mmc; (void)allow; abort(); }
''' + function(source, "smc_mmc_drain_stop") + "\n" + function(source, "smc_poll") + r'''

static int check_input(int up)
{
    static const uint8_t controls[3][3] = {
        {0xE0, 0, 100}, {0xB0, 16, 1}, {0x90, 0x18, 127}
    };
    /* The transport already reported this state. It does not retransmit it. */
    ble_central_link_notify(up);
    for (unsigned i = 0; i < 3; i++) smc_ble_midi(controls[i], 3);
    smc_poll();
    if (smc.up != up || dispatched != (up ? 3u : 0u) ||
        (up && memcmp(controls, observed, sizeof controls)) ||
        (!up && (smc_rx_diag() >> 24) != 2u)) {
        fprintf(stderr, "FAIL: transport=%d application=%u dispatched=%u reason=%u\n",
                up, smc.up, dispatched, (unsigned)(smc_rx_diag() >> 24));
        return 1;
    }
    return 0;
}

int main(int argc, char **argv)
{
    if (argc != 3) return 2;
    int mode = atoi(argv[1]), site = atoi(argv[2]);
    proj.set.bt = PROJ_BT_SMC_CENTRAL;
    if (mode <= 1) {
        /* A newer reconnect/disconnect arrives after the old state was read. */
        int up = mode == 0;
        ble_central_link_notify(up); smc_poll();
        ble_central_link_notify(!up);
        interrupt_at = site; interrupt_up = up;
        smc_poll(); smc_poll();
        if (interrupt_at) return 3;
        return check_input(up);
    }
    ble_central_link_notify(1); smc_poll();
    smc.picked = 0x55; smc.seen = 0xAA; smc.known[5] = 1;
    if (mode == 2) {
        /* Unchanged connection must not reset pickup or republish notices. */
        unsigned before = notices;
        for (unsigned i = 0; i < 32; i++) smc_poll();
        if (notices != before || smc.picked != 0x55 || smc.seen != 0xAA ||
            !smc.known[5]) return 4;
    } else if (mode == 3) {
        /* Coalesced down/up remains a new link even if the final state is up. */
        ble_central_link_notify(0); ble_central_link_notify(1); smc_poll();
        if (smc.picked || smc.seen || smc.known[5]) return 5;
    } else if (mode == 4) {
        /* A project lock/reset must leave a newer link publication available. */
        locked = 1;
        ble_central_link_notify(0); smc_poll(); smc_project_reset();
        ble_central_link_notify(1); smc_poll();
        locked = 0; smc_poll();
    } else if (mode == 5) {
        smc.solo = 1; solo = 1;
        ble_central_link_notify(0); smc_poll();
        if (smc.solo || solo || smc.picked || smc.seen) return 6;
        return check_input(0);
    } else if (mode == 6) {
#ifdef LINK_GENERATION
        /* Zero is a valid disconnected publication after unsigned wrap. */
        smc_link_published = smc_link_seen = UINT32_MAX;
        ble_central_link_notify(0); smc_poll();
        if (smc_link_published != 0 || smc.up) return 7;
        ble_central_link_notify(1); smc_poll();
#else
        return 77;
#endif
    } else if (mode == 7) {
#ifdef LINK_GENERATION
        ble_central_link_notify(0); smc_poll();
        smc_link_published = smc_link_seen = UINT32_MAX - 1u;
        ble_central_link_notify(1); smc_poll();
        if (smc_link_published != 1u || !smc.up) return 8;
#else
        return 77;
#endif
    } else return 2;
    return check_input(1);
}
'''

cases = [("reconnect", 0, 1), ("reconnect-late", 0, 2),
         ("disconnect", 1, 1), ("disconnect-late", 1, 2),
         ("stable-pickup", 2, 0), ("coalesced-edges", 3, 0),
         ("project-reset", 4, 0), ("disconnect-clears-solo", 5, 0)]
if has_generation:
    cases += [("wrap-down", 6, 0), ("wrap-up", 7, 0)]

with tempfile.TemporaryDirectory(prefix="smc-link-") as tmp:
    c = Path(tmp) / "test.c"
    executable = Path(tmp) / "test"
    c.write_text(harness)
    flags = shlex.split(os.environ.get("SAN_FLAGS", ""))
    if has_generation:
        flags.append("-DLINK_GENERATION")
    subprocess.run([os.environ.get("CC", "cc"), "-std=c99", "-O2", "-g",
                    "-Wall", "-Wextra", "-Werror", *flags,
                    "-I" + str(ROOT / "firmware/src"),
                    "-I" + str(ROOT / "tests/host"),
                    str(c), "-o", str(executable)], check=True)
    failures = []
    for label, mode, site in cases:
        result = subprocess.run([str(executable), str(mode), str(site)], check=False)
        print(f'{"PASS" if result.returncode == 0 else "FAIL"} {label}', flush=True)
        if result.returncode:
            failures.append((label, result.returncode))
    if failures:
        raise SystemExit(f"FAIL: {len(failures)}/{len(cases)} SMC link cases: {failures}")
print(f"PASS: {len(cases)} SMC link cases preserve reconnect, disconnect, pickup, reset and wrap")

/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 audio out: ALNK0 I2S -> external codec, double-buffered DMA
 * The application owns the buffer: two halves
 * of half_words int32 (L, R, 24-bit left-justified), zeroed before init.
 *
 *   fm1_audio_init(buf, half_words, isr, prio)  codec and ALNK0 bring-up;
 *                         isr = asm wrapper (fm1_isr.S) for FM1_IRQ_ALNK0
 *   in the ISR:   p = fm1_audio_pending();  fm1_audio_ack_aux(p);
 *                 if (p & FM1_AUDIO_HALF) { fill fm1_audio_free_half();
 *                                           fm1_audio_ack_half(); }
 *   fm1_audio_stop()      DMA off (crash screen, UBOOT): no looping buzz
 */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"
#include "fm1_time.h"
#include "fm1_irq.h"
#include "fm1_gpio.h"

#define FM1_ALNK 0x12E00u
#define FM1_ALNK_CON0 (*(volatile uint16_t *)(FM1_ALNK + 0x00u))
#define FM1_ALNK_CON1 (*(volatile uint16_t *)(FM1_ALNK + 0x04u))
#define FM1_ALNK_CON2 (*(volatile uint8_t *)(FM1_ALNK + 0x08u))
#define FM1_ALNK_CON3 (*(volatile uint8_t *)(FM1_ALNK + 0x0Cu))
#define FM1_ALNK_ADR3 (*(volatile uint32_t *)(FM1_ALNK + 0x1Cu))
#define FM1_ALNK_LEN (*(volatile uint16_t *)(FM1_ALNK + 0x20u))
#define FM1_CLK_CON2 (*(volatile uint32_t *)0x10014u)
#define FM1_IOMAP_CON5 (*(volatile uint32_t *)0x51030u)
#define FM1_AUDIO_HALF 0x80u      /* CON2 pending: a half buffer is free */

static void fm1__pc_out(uint32_t bit, int v)   /* codec control lines on PC0/1/2/6 */
{
    uint32_t m = 1u << bit;
    FM1_PR(FM1_PC, FM1_DIE) |= m;
    if (v)
        FM1_PR(FM1_PC, FM1_OUT) |= m;
    else
        FM1_PR(FM1_PC, FM1_OUT) &= ~m;
    FM1_PR(FM1_PC, FM1_DIR) &= ~m;
}

FM1_INLINE void fm1_audio_init(int32_t *buf, uint32_t half_words, void (*isr)(void), uint32_t prio)
{
    fm1__pc_out(6, 0);
    fm1_delay_ms(5);
    FM1_ALNK_CON0 = 0;
    FM1_ALNK_CON1 = 0;
    FM1_ALNK_CON2 = 0;
    FM1_ALNK_CON3 = 0;
    FM1_IOMAP_CON5 &= ~0xC0u;
    FM1_ALNK_CON3 |= 3u;
    fm1__pc_out(0, 1);
    FM1_ALNK_CON0 |= 0x100u;
    fm1__pc_out(2, 1);
    fm1__pc_out(1, 1);
    FM1_ALNK_CON0 |= 0x80u;
    FM1_ALNK_CON0 &= ~0x40u;
    FM1_ALNK_LEN = half_words;
    FM1_ALNK_CON0 &= ~0x400u;
    FM1_ALNK_CON0 &= ~0x200u;
    FM1_CLK_CON2 &= 0xFFFFF0FFu;
    FM1_ALNK_CON3 &= ~0x1Cu;
    FM1_ALNK_CON3 = (uint8_t)((FM1_ALNK_CON3 & 0x1Fu) | 0x80u);
    FM1_ALNK_CON1 |= 1u << 12;
    FM1_ALNK_CON1 |= 1u << 14;
    FM1_ALNK_ADR3 = (uint32_t)(uintptr_t)buf;
    fm1__pc_out(6, 1);
    FM1_ALNK_CON1 &= ~(1u << 15);
    FM1_ALNK_CON2 = 0x0Fu;
    fm1_irq_attach(FM1_IRQ_ALNK0, isr, prio);
    FM1_ALNK_CON0 |= 0x800u;
    fm1_delay_ms(5);
    fm1__pc_out(6, 1);
}

FM1_INLINE uint8_t fm1_audio_pending(void) { return FM1_ALNK_CON2; }
FM1_INLINE void fm1_audio_ack_aux(uint8_t p)   /* the other three pendings */
{
    if (p & 0x10u)
        FM1_ALNK_CON2 |= 1u;
    if (p & 0x20u)
        FM1_ALNK_CON2 |= 2u;
    if (p & 0x40u)
        FM1_ALNK_CON2 |= 4u;
}
FM1_INLINE uint32_t fm1_audio_free_half(void) { return ((FM1_ALNK_CON0 >> 15) & 1u) ^ 1u; }   /* 0 / 1 */
FM1_INLINE void fm1_audio_ack_half(void) { FM1_ALNK_CON2 |= 0x08u; }
FM1_INLINE void fm1_audio_stop(void) { FM1_ALNK_CON0 &= ~0x800u; }

/* SPDX-License-Identifier: GPL-3.0-only */
#pragma once
#include <stdint.h>

/* Stock User preset MMC commands: 32 strip keys in M/S/R/SELECT order, then
 * eleven global keys. The DAW note values are the same button identifiers. */
static inline uint8_t smc_mmc_note(uint8_t cmd)
{
    static const uint8_t base[4] = {0x10, 0x08, 0x00, 0x18};
    static const uint8_t tail[11] = {0x5E, 0x5D, 0x5F, 0x5B, 0x5C, 0x2E, 0x2F,
                                      0x60, 0x61, 0x62, 0x63};
    if (cmd >= 1u && cmd <= 32u)
        return (uint8_t)(base[(cmd - 1u) & 3u] + ((cmd - 1u) >> 2));
    return cmd >= 33u && cmd <= 43u ? tail[cmd - 33u] : 0xFFu;
}

static inline int smc_pickup_reached(uint8_t prior, int seen, uint8_t target, uint8_t current)
{
    if (seen && ((prior < target) != (current < target)))
        return 1;
    return current + 2u >= target && current <= target + 2u;
}

static inline int smc_relative(uint8_t value)
{
    return (value & 0x40u) ? -(int)(value & 0x3Fu) : (int)(value & 0x3Fu);
}

/* Host USB/peripheral BLE has no controller identity: opt-in User mode and
 * channel 16 isolate these messages from instruments and APC40 feedback. */
static inline int smc_host_accept(uint8_t status, uint8_t data1, int user_mode)
{
    uint8_t type = status & 0xF0u, a = data1 & 0x7Fu;
    if (!user_mode || (status & 15u) != 15u)
        return 0;
    if (type == 0xB0u)
        return (a >= 16u && a < 24u) || (a >= 40u && a < 48u);
    if (type != 0x90u && type != 0x80u)
        return 0;
    return a < 32u || a == 0x2Eu || a == 0x2Fu || a == 0x30u || a == 0x31u ||
           (a >= 0x5Bu && a <= 0x5Fu) || (a >= 0x60u && a <= 0x63u);
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Host proof: Chicago Crush/Decimator insert holds + quantises vs dry native303. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "bass303.h"
#include "chicago_fx.h"
#include "chicago_crush.h"

static int fails;
#define CHECK(c, ...)                                                                                                  \
    do {                                                                                                               \
        if (!(c)) {                                                                                                    \
            printf("FAIL " __VA_ARGS__);                                                                               \
            printf("\n");                                                                                              \
            fails++;                                                                                                   \
        }                                                                                                              \
    } while (0)

static float buf[8192];
static float dry[8192];

static void render_note(bass303_t *b, float *out, int n)
{
    int pos = 0;
    bass303_init(b);
    bass303_set(b, BASS303_CUTOFF, 100);
    bass303_set(b, BASS303_RESO, 40);
    bass303_set(b, BASS303_ENVMOD, 0);
    bass303_set(b, BASS303_WAVE, 0);
    bass303_set(b, BASS303_GNAW, 0);
    bass303_set(b, BASS303_BITE, 0);
    bass303_set(b, BASS303_VOLUME, 100);
    bass303_set(b, BASS303_DRIVE, 0);
    bass303_set(b, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_note_on_velocity(b, 48, 0, 0, 100);
    while (pos < n) {
        int m = n - pos > 128 ? 128 : n - pos;
        bass303_render(b, out + pos, m);
        pos += m;
    }
}

static int count_holds(const float *x, int n)
{
    int i, holds = 0;
    for (i = 1; i < n; i++) {
        if (x[i] == x[i - 1])
            holds++;
    }
    return holds;
}

static double rms_delta(const float *a, const float *b, int n)
{
    double s = 0;
    int i;
    for (i = 0; i < n; i++) {
        double d = (double)a[i] - (double)b[i];
        s += d * d;
    }
    return sqrt(s / (double)n);
}

static void test_supported_flags(void)
{
    CHECK(chi_fx_supported(CHI_FX_DECIM), "Crush supported");
    CHECK(chi_fx_is_insert(CHI_FX_DECIM), "Crush is insert");
    CHECK(chi_fx_is_crush_insert(CHI_FX_DECIM), "Crush insert helper");
    CHECK(!chi_fx_is_not_yet(CHI_FX_DECIM), "Crush not NOT_YET");
    CHECK(strstr(CHI_FX_TYPE_N[CHI_FX_DECIM], "—") == 0, "Crush label has no em-dash");
}

static void test_map_clears_sends(void)
{
    chicago_fx_out_t o;
    chicago_fx_map(CHI_FX_DECIM, 70, 127, 0, &o);
    CHECK(o.touch == CHI_FX_W_CLEAR_SENDS, "Crush map clears sends");
    CHECK(!(o.touch & CHI_FX_W_DIST), "Crush does not steal master Dist");
    CHECK(!(o.touch & CHI_FX_W_DRIVE), "Crush does not steal master Drive");
}

static void test_hold_and_delta(void)
{
    bass303_t b;
    chi_crush_t crush;
    int n = 4096, skip = 512;
    int holds_dry, holds_crush;
    double delta;
    render_note(&b, dry, n);
    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_crush_init(&crush);
    /* High Edit1 — insert is full-wet; sample-and-hold creates equal neighbours. */
    chi_crush_set(&crush, 110, 0);
    chi_crush_process(&crush, buf + skip, n - skip);
    holds_dry = count_holds(dry + skip, n - skip);
    holds_crush = count_holds(buf + skip, n - skip);
    CHECK(holds_crush > holds_dry + 200, "crush increases held-sample count (dry %d crush %d)", holds_dry,
          holds_crush);
    delta = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta > 1e-4, "crush insert changes waveform (rms delta %g)", delta);
    /* Unset insert (init wet=0) must be a no-op */
    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_crush_init(&crush);
    chi_crush_process(&crush, buf + skip, n - skip);
    CHECK(memcmp(buf + skip, dry + skip, (size_t)(n - skip) * sizeof(float)) == 0, "unset crush leaves PCM unchanged");
}

int main(void)
{
    test_supported_flags();
    test_map_clears_sends();
    test_hold_and_delta();
    if (fails) {
        printf("%d FAIL(s)\n", fails);
        return 1;
    }
    printf("PASS chicago_crush\n");
    return 0;
}

